CREATE TABLE public.onedrive_access (user_id uuid PRIMARY KEY, can_write boolean NOT NULL DEFAULT false, ai_enabled boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.onedrive_access TO authenticated; GRANT ALL ON public.onedrive_access TO service_role;
ALTER TABLE public.onedrive_access ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_access ON public.onedrive_access FOR SELECT TO authenticated USING(user_id=auth.uid());
INSERT INTO public.onedrive_access(user_id,can_write) SELECT s.user_id,true FROM public.onedrive_sync_state s WHERE public.is_admin(s.user_id);
CREATE TABLE public.onedrive_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,drive_id text NOT NULL,item_id text NOT NULL,parent_id text,name text NOT NULL,is_folder boolean NOT NULL DEFAULT false,size bigint NOT NULL DEFAULT 0,mime_type text,etag text,web_url text,modified_at timestamptz,deleted boolean NOT NULL DEFAULT false,documento_id uuid REFERENCES public.documenti(id),updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,drive_id,item_id));
GRANT SELECT ON public.onedrive_items TO authenticated; GRANT ALL ON public.onedrive_items TO service_role;
ALTER TABLE public.onedrive_items ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_items ON public.onedrive_items FOR SELECT TO authenticated USING(user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.onedrive_access a WHERE a.user_id=auth.uid()));
CREATE INDEX onedrive_items_parent ON public.onedrive_items(user_id,parent_id) WHERE NOT deleted;
CREATE TABLE public.onedrive_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,item_id text,operation text NOT NULL,payload jsonb NOT NULL DEFAULT '{}',status text NOT NULL DEFAULT 'pending',attempts integer NOT NULL DEFAULT 0,error text,next_attempt_at timestamptz NOT NULL DEFAULT now(),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),idempotency_key text NOT NULL UNIQUE);
GRANT SELECT ON public.onedrive_jobs TO authenticated; GRANT ALL ON public.onedrive_jobs TO service_role;
ALTER TABLE public.onedrive_jobs ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_jobs ON public.onedrive_jobs FOR SELECT TO authenticated USING(user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.onedrive_access a WHERE a.user_id=auth.uid()));
ALTER TABLE public.onedrive_sync_state ADD COLUMN cursor_next text, ADD COLUMN scan_status text NOT NULL DEFAULT 'idle', ADD COLUMN lease_until timestamptz, ADD COLUMN scan_error text, ADD COLUMN scan_pages integer NOT NULL DEFAULT 0, ADD COLUMN subscription_id text, ADD COLUMN subscription_expires_at timestamptz;
COMMENT ON COLUMN public.onedrive_sync_state.root_folder_id IS 'DEPRECATED: whole-drive sync uses root; retained for compatibility';
REVOKE INSERT, UPDATE, DELETE ON public.onedrive_sync_state,public.onedrive_sync_eventi FROM authenticated;
CREATE OR REPLACE FUNCTION public.claim_onedrive_sync(p_user_id uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.onedrive_sync_state SET lease_until=now()+interval '90 seconds' WHERE user_id=p_user_id AND stato='attiva' AND (lease_until IS NULL OR lease_until<now()); RETURN FOUND; END; $$;
REVOKE ALL ON FUNCTION public.claim_onedrive_sync(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.claim_onedrive_sync(uuid) TO service_role;